package dev.underthebedrock.horror;
import dev.underthebedrock.UnderTheBedrockPlugin;import dev.underthebedrock.integration.BetterModelIntegration;import dev.underthebedrock.world.VoidWorldManager;
import org.bukkit.Location;import org.bukkit.World;import org.bukkit.entity.ArmorStand;import org.bukkit.entity.Player;import org.bukkit.event.EventHandler;import org.bukkit.event.Listener;import org.bukkit.event.player.PlayerJoinEvent;import org.bukkit.scheduler.BukkitTask;import org.bukkit.util.Vector;
import java.util.HashMap;import java.util.Map;import java.util.Random;import java.util.UUID;
/** Scheduled, per-player model apparition controller. Never force-loads chunks. */
public final class HorrorEntityController implements Listener {
 private record Encounter(UUID target,EntityArchetype type,ArmorStand shell){}private final UnderTheBedrockPlugin plugin;private final VoidWorldManager worlds;private final OccurrenceDirector director;private final BetterModelIntegration models;private final Map<UUID,Encounter> active=new HashMap<>();private final Random random=new Random();private BukkitTask task;private boolean warned;
 public HorrorEntityController(UnderTheBedrockPlugin p,VoidWorldManager w,OccurrenceDirector d,BetterModelIntegration m){plugin=p;worlds=w;director=d;models=m;}
 public void start(){if(task!=null)return;plugin.getServer().getPluginManager().registerEvents(this,plugin);long ticks=Math.max(1,plugin.getConfig().getLong("horror.director.check-interval-seconds",12))*20L;task=plugin.getServer().getScheduler().runTaskTimer(plugin,this::tick,ticks,ticks);}
 public void stop(){if(task!=null)task.cancel();task=null;clearAll();}
 private void tick(){if(!worlds.isActive()){clearAll();return;}World w=worlds.getWorld();if(w==null)return;for(Player p:w.getPlayers()){Encounter e=active.get(p.getUniqueId());if(e!=null)update(p,e);else attempt(p);}active.entrySet().removeIf(e->{Player p=plugin.getServer().getPlayer(e.getKey());if(p!=null&&p.getWorld().equals(w))return false;remove(e.getValue());return true;});}
 private void attempt(Player p){if(models.availableModels().isEmpty()){if(!warned){warned=true;plugin.getLogger().warning("No BetterModel models registered; entity encounters paused.");}return;}Location spawn=findSpawn(p);if(spawn==null)return;var choice=director.trySelectEntityEncounter(p);if(choice.isEmpty())return;EntityArchetype type=choice.get();String model=plugin.getConfig().getString("horror.entities.models."+type.name().toLowerCase(),"watcher");if(!models.availableModels().contains(model)){plugin.getLogger().warning("Missing BetterModel key '"+model+"' for "+type+".");return;}
  ArmorStand shell=p.getWorld().spawn(spawn,ArmorStand.class,s->{s.setInvisible(true);s.setMarker(true);s.setGravity(false);s.setInvulnerable(true);s.setSilent(true);s.setCollidable(false);s.setPersistent(false);s.setCustomNameVisible(false);});
  if(models.attachModel(shell,model).isEmpty()){shell.remove();plugin.getLogger().warning("Could not attach BetterModel '"+model+"'.");return;}
  for(Player viewer:p.getWorld().getPlayers())if(!viewer.getUniqueId().equals(p.getUniqueId()))viewer.hideEntity(plugin,shell);
  active.put(p.getUniqueId(),new Encounter(p.getUniqueId(),type,shell));director.recordEntityEncounter(p,type);p.playSound(p.getLocation(),org.bukkit.Sound.ENTITY_ENDERMAN_STARE,.12f,.55f);
 }
 private Location findSpawn(Player p){Location o=p.getLocation();Vector f=o.getDirection().setY(0).normalize();if(f.lengthSquared()<.01)f=new Vector(0,0,1);int y=plugin.getConfig().getInt("world.floor-y",64);for(int i=0;i<12;i++){double a=Math.toRadians(105+random.nextDouble()*150);Vector v=f.clone().rotateAroundY(a).multiply(26+random.nextDouble()*12);int x=o.getBlockX()+v.getBlockX(),z=o.getBlockZ()+v.getBlockZ();if(!p.getWorld().isChunkLoaded(Math.floorDiv(x,16),Math.floorDiv(z,16)))continue;Location l=new Location(p.getWorld(),x+.5,y+1,z+.5);if(l.distanceSquared(o)>=400)return l;}return null;}
 private void update(Player p,Encounter e){ArmorStand s=e.shell();if(!s.isValid()||!s.getWorld().equals(p.getWorld())){remove(e);active.remove(p.getUniqueId());return;}double d=s.getLocation().distanceSquared(p.getLocation());if(d>9216||(d<576&&p.hasLineOfSight(s))){remove(e);active.remove(p.getUniqueId());return;}if(e.type()==EntityArchetype.AGGRESSOR&&director.memory(p.getUniqueId()).provocation()>=20&&d>144){Vector v=p.getLocation().toVector().subtract(s.getLocation().toVector()).normalize();Location n=s.getLocation().add(v.multiply(1.15));n.setY(plugin.getConfig().getInt("world.floor-y",64)+1);if(s.getWorld().isChunkLoaded(n.getBlockX()>>4,n.getBlockZ()>>4))s.teleport(n);}else if(e.type()==EntityArchetype.WANDERER&&random.nextDouble()<.08){Location n=s.getLocation().add(random.nextInt(9)-4,0,random.nextInt(9)-4);n.setY(plugin.getConfig().getInt("world.floor-y",64)+1);if(s.getWorld().isChunkLoaded(n.getBlockX()>>4,n.getBlockZ()>>4))s.teleport(n);}}
 @EventHandler public void onJoin(PlayerJoinEvent e){for(var encounter:active.values())if(encounter.shell().isValid()&&encounter.shell().getWorld().equals(e.getPlayer().getWorld())&&!encounter.target().equals(e.getPlayer().getUniqueId()))e.getPlayer().hideEntity(plugin,encounter.shell());}
 private void remove(Encounter e){if(e.shell().isValid())e.shell().remove();}private void clearAll(){for(Encounter e:active.values())remove(e);active.clear();}
}